mapper.select:
SELECT song.id, song.file_size, song.modified_at, song.result_json, song.embedded_tags_json, song.source_id, song.relative_path, source.name AS source_name, song.scanned_at, song.parser_profile_id, song.parser_revision, song.selected_rule_id, meta.track_json AS metadata_track, meta.fields_json AS metadata_fields, meta.applied_at AS metadata_applied_at, meta.origins_json AS metadata_origins, meta.fingerprint AS metadata_fingerprint FROM media_song song JOIN media_source source ON source.id = song.source_id LEFT JOIN song_metadata meta ON meta.song_id = song.id
song.source_id = #{sourceId}
AND song.id IN #{id}
ORDER BY song.id LIMIT 5001

sql.where:
item.batch_id=#{batchId}
    AND item.status IN ('AUTO_APPLIED','MANUAL_APPLIED')AND item.status=#{status}
    AND (LOWER(item.title) LIKE LOWER(#{keyword}) ESCAPE '!' OR LOWER(item.artists_json) LIKE LOWER(#{keyword}) ESCAPE '!')
